O = {
"c399:xo53_1_95": ("폐쇄성 질환의 **날숨유량**", "폐쇄성 질환은 기도가 좁아 날숨유량이 **줄어요**. 유량-용적 곡선이 오목해지고 높은 용적 쪽으로 이동해요.", "폐쇄성 질환은 날숨유량이 **감소**한다.", "폐쇄 = 못 내쉰다", 4),
"c399:xo52_1_93": ("폐쇄성 질환의 **FEV1**", "폐쇄성 질환은 공기가 갇혀 잔기량·기능잔기용량이 늘고, **FEV1과 FEV1/FVC는 감소**해요.", "폐쇄성 폐질환에서는 FEV1이 **감소**한다.", "폐쇄 = FEV1/FVC↓, 제한 = 용적 전체↓", 5),
"c399:xo51_1_91": ("**가스교환** 능력 검사", "가스교환 능력은 일산화탄소를 쓰는 **폐확산능력(DLCO)** 으로 봐요. 최대날숨유속은 기도폐쇄를 봐요.", "가스교환 능력은 **폐확산능력(DLCO)** 검사로 본다.", "가스교환 = DLCO, 기도 = PEF", 3),
"c399:xo50_1_93": ("최대 날숨 후 **남은 공기**", "최대로 내쉰 뒤 남은 공기량은 **잔기량**이에요. 기능잔기용량은 편안히 내쉰 뒤 남은 양(날숨예비량 + 잔기량)이에요.", "최대로 내쉰 뒤 남은 공기량은 **잔기량**이다.", "최대 후 = 잔기량, 편안히 후 = 기능잔기용량", 5),
"c400:xo52_1_92": ("**기도폐쇄** 평가", "기도폐쇄는 **최대날숨유속(PEF)** 으로 봐요. 폐확산능력은 가스교환 검사예요.", "기도폐쇄 정도는 **최대날숨유속**으로 평가한다.", "폭발적으로 내쉬기 = PEF", 3),
"c400:xt52_1_92": ("**폭발적으로 내쉬기**", "최대로 들이쉰 뒤 폭발적으로 내쉰 최고 속도로 기도폐쇄를 보는 검사가 **최대날숨유속(PEF)** 이에요.", "'폐확산능력'으로 바꾸면 틀려요.", "PEF = 기도", 3),
"c400:xo51_1_93": ("**헬륨 희석법**", "헬륨 희석법은 폐활량계로 못 재는 **잔기량·폐용적**을 재요. 호흡근력은 최대들숨압·최대날숨압으로 재요.", "헬륨 희석법은 **잔기량·폐용적**을 측정한다.", "헬륨 = 잔기량", 3),
"c400:xt51_1_93": ("**호흡근력** 측정", "호흡근력은 **최대들숨압·최대날숨압(MIP·MEP)** 으로 재요.", "'헬륨 희석법'으로 바꾸면 틀려요.", "근력 = 압력", 3),
"c401:xo52_1_68": ("**오목가슴**", "오목가슴은 복장뼈가 안으로 들어가 앞뒤 직경이 **감소**해요. 앞뒤 직경이 늘어난 것은 술통가슴이에요.", "오목가슴은 앞뒤 직경이 **감소**한 가슴이다.", "오목 = 줄고, 술통 = 늘고", 3),
"c401:xt52_1_68": ("앞뒤 직경 **증가**", "폐기종에서 공기가 갇혀 가슴우리 앞뒤 직경이 늘어난 것이 **술통가슴**이에요.", "'오목가슴'으로 바꾸면 틀려요.", "폐기종 = 술통", 3),
"c402:xo53_1_93": ("**T파**의 의미", "T파는 **심실 재분극**이에요. 심방 탈분극은 P파예요.", "T파는 **심실 재분극**이다.", "P 심방 탈분극, QRS 심실 탈분극, T 심실 재분극", 5),
"c402:xo52_1_90": ("**심방 재분극**의 위치", "심방 재분극은 심실 탈분극과 겹쳐 **QRS에 가려져** 보이지 않아요.", "심방 재분극은 **QRS 군에 가려진다**.", "심방 재분극은 숨어 있다", 4),
"c402:xo51_1_90": ("**1도 방실차단**", "1도 방실차단은 **PR 간격이 0.20초를 넘어** 길어지는 것이에요. QRS 폭과는 관계없어요.", "1도 방실차단에서는 **PR 간격**이 길어진다.", "1도 = PR 연장", 5),
"c402:xo50_1_14": ("**T파**", "T파는 심실 재분극이에요. 맞는 문장이에요.", "'심방 탈분극'으로 바꾸면 틀려요.", "T = 심실 재분극", 5),
"c402:xo50_1_91": ("정상 **PR 간격**", "정상 PR 간격은 **0.12~0.20초**예요. 맞는 문장이에요. 0.20초를 넘으면 1도 방실차단이에요.", "'0.20~0.30초'로 바꾸면 틀려요.", "PR 0.12~0.20", 4),
"c403:xo52_2_57": ("보그 척도 **11**", "보그(6~20)에서 11은 **가볍다**, 17이 아주(매우) 힘들다예요.", "보그 척도에서 17이 '아주 힘들다'다(11은 가볍다).", "11 가볍다, 13 약간 힘들다, 17 아주 힘들다", 4),
"c403:xt52_2_57": ("**'아주 힘들다'** 점수", "보그(6~20) 척도에서 '아주 힘들다'는 **17**이에요.", "'11'로 바꾸면 틀려요.", "17 = 아주 힘들다", 4),
"c403:xo51_1_92": ("**급성 심근염**과 운동부하검사", "급성 심근염과 대동맥박리는 운동부하검사의 **금기**예요.", "급성 심근염은 운동부하검사 **금기**다.", "급성 염증·박리 = 금기", 4),
"c403:xt51_1_92": ("운동부하검사 **적응증**", "**안정협심증**은 운동부하검사로 허혈을 평가할 수 있는 적응증이에요.", "'급성 심근염'으로 바꾸면 틀려요.", "안정 = 적응, 급성 = 금기", 4),
"c403:xo50_1_90": ("환자의 **중단 요청**", "환자가 중단을 요구하면 그 자체가 **중단 기준**이에요.", "환자가 중단을 요구하면 검사를 **중단**한다.", "그만하자고 하면 그만", 3),
"c403:xt50_1_90": ("트레드밀 **강도 증가 방식**", "트레드밀 운동부하검사는 속도·경사를 **단계적·점진적으로** 올려요.", "'처음부터 최대 강도'로 바꾸면 틀려요.", "부하는 계단처럼", 3),
"c404:xo53_1_94": ("**깊은정맥혈전증** 검사", "깊은정맥혈전증은 **호만 징후** 등으로 의심해요. 톰슨 검사는 아킬레스힘줄 파열 검사예요.", "깊은정맥혈전증은 **호만 징후**로 확인한다.", "호만 = 혈전, 톰슨 = 아킬레스", 4),
"c404:xt53_1_94": ("종아리 **부종·열감·압통**", "종아리 부종·열감·압통은 깊은정맥혈전증 소견이고, **호만 징후**로 확인해요.", "'톰슨 검사'로 바꾸면 틀려요.", "호만 = 혈전", 4),
"c404:xo51_1_77": ("**호만 징후** 방법", "호만 징후는 무릎을 편 채 발목을 **발등굽힘**시켜 종아리 통증을 봐요.", "호만 징후는 발목을 **발등굽힘**시켜 확인한다.", "발등굽힘 = 종아리를 늘린다", 4),
"c404:xt51_1_77": ("발등굽힘 + **종아리 압박 통증**", "발목을 발등굽힘할 때 종아리가 아프면 **깊은정맥혈전증(호만 징후)** 을 의심해요.", "'아킬레스힘줄 파열'로 바꾸면 틀려요.", "호만 = 혈전", 4),
"c405:xo52_2_63": ("**겨드랑 화상** 자세", "겨드랑 화상은 모음 자세로 두면 구축이 생기므로 **벌림·굽힘·가쪽돌림** 자세로 둬요.", "겨드랑 화상은 어깨 **벌림·굽힘·가쪽돌림** 자세로 둔다.", "편한 자세 = 구축 자세, 반대로 둔다", 4),
"c405:xt52_2_63": ("겨드랑 3도 화상 **구축 방지**", "구축 방지 자세는 어깨 **벌림·굽힘·가쪽돌림**이에요.", "'어깨 모음'으로 바꾸면 틀려요.", "겨드랑은 벌린다", 4),
"c405:xo51_1_94": ("**3도 화상**의 통증", "3도 화상은 신경까지 파괴돼 오히려 **통증이 적어요**. 심한 통증은 2도예요.", "3도 화상은 신경이 파괴돼 **통증이 적다**.", "가장 아픈 건 2도", 4),
"c405:xt51_1_94": ("**물집 + 심한 통증**", "물집과 심한 통증이 있는 것은 **2도(부분층)** 화상이에요.", "'3도'로 바꾸면 틀려요.", "물집 = 2도", 4),
"c406:xo53_1_97": ("**유착** 위치 찾기", "유착 부위와 이동성은 피부를 집어 굴려 보는 **피부굴림 검사**로 찾아요.", "**피부굴림 검사**로 유착 부위를 확인한다.", "굴려 보면 붙은 곳이 걸린다", 2),
"c406:xo52_1_94": ("**광과민** 확인", "햇빛 노출 후 홍반은 **광검사**로 확인해요. 투베르쿨린 검사는 결핵 감염 검사예요.", "햇빛 노출 후 홍반은 **광검사**로 확인한다.", "투베르쿨린 = 결핵", 2),
"c406:xo52_1_95": ("**태선화**", "태선화는 오래 긁어 피부가 가죽처럼 **두껍고 거칠어지며** 주름이 깊어지는 변화예요.", "태선화는 피부가 **두껍고 거칠어지는** 것이다.", "긁으면 가죽처럼 두꺼워진다", 2),
"c406:xo50_1_95": ("**면봉**의 측정 용도", "멸균 면봉은 상처 바닥이나 굴(터널)에 넣어 **깊이**를 재요.", "면봉으로는 상처 **깊이**를 측정한다.", "면봉 = 깊이", 2),
}
